import React from 'react';
import { useTheme, alpha } from '@mui/material/styles';
import { Box, Grid, IconButton, Stack, Tab, Tabs, Typography } from '@mui/material';
import { useDispatch, useSelector } from 'react-redux';
import { CaretLeft } from 'phosphor-react';
import { UpdateSidebarType } from '../../redux/slices/app';
import { DocMsg } from './Conversation';
import { extractURL } from '../../utils/urlProcess';
import { convertToIST } from '../../utils/formatTime';
import truncateString from '../../utils/truncate';

const SharedMessages = () => {
    const theme = useTheme();

    const dispatch = useDispatch();

    const [value, setValue] = React.useState(0);

    const handleChange = (event, newValue) => {
        setValue(newValue);
    };

    const { current_messages } = useSelector((state) => state.conversation.direct_chat);


    return (
        <Box sx={{ width: 320, maxHeight: "100vh" }}>
            <Stack sx={{ height: "100%" }}>
                {/* Header */}
                <Box
                    zIndex={2}
                    sx={{
                        boxShadow: "0px 0px 2px rgba(0, 0, 0, 0.25)",
                        width: "100%",
                        backgroundColor:
                            theme.palette.mode === "light"
                                ? "#F8FAFF"
                                : theme.palette.background,
                    }}
                >
                    <Stack
                        sx={{ height: "100%", p: 2 }}
                        direction="row"
                        alignItems={"center"}
                        spacing={3}
                    >
                        <IconButton
                            onClick={() => {
                                dispatch(UpdateSidebarType("CONTACT"));
                            }}
                        >
                            <CaretLeft />
                        </IconButton>
                        <Typography variant="subtitle2">Shared Messages</Typography>
                    </Stack>
                </Box>

                {/* Tabs */}
                <Tabs centered value={value} onChange={handleChange}>
                    <Tab label="Media" />
                    <Tab label="Links" />
                    <Tab label="Docs" />
                </Tabs>
                <Stack
                    sx={{
                        height: "100%",
                        position: "relative",
                        flexGrow: 1,
                        overflowY: "scroll",
                    }}
                    p={3}
                    spacing={value === 1 ? 1 : 5}
                >
                    {
                        (() => {
                            switch (value) {
                                case 0:
                                    // Images
                                    return <Grid container spacing={2}>
                                        {
                                            current_messages?.map((el) => {
                                                if (el?.type === "msg" && el.subtype === "MEDIA") {
                                                    if (el.mediaType === "image") {
                                                        return <Grid item xs={4}>
                                                            <a href={el.media} target='_blank' rel="noopener noreferrer">
                                                                <img width={"100%"} src={el.media} alt={el.mediaType} />
                                                            </a>
                                                        </Grid>
                                                    } else if (el.mediaType === "video") {
                                                        return <Grid item xs={4}>
                                                            <a href={el.media} target='_blank' rel="noopener noreferrer">
                                                                <video width={"100%"} src={el.media} alt={el.mediaType} />
                                                            </a>
                                                        </Grid>
                                                    }
                                                }
                                            })
                                        }
                                    </Grid>
                                case 1:
                                    return current_messages?.map((el) => {
                                        if (el?.type === "msg" && el.subtype === "LINK") {
                                            return (
                                                <Stack
                                                    direction={el.incoming ? "row" : "row-reverse"}
                                                    justifyContent={el.incoming ? "start" : "end"}
                                                    sx={{
                                                        maxWidth: "100%", // Ensure the message bubble isn't too wide
                                                    }}
                                                >
                                                    <Box
                                                        px={1.5}
                                                        py={1}
                                                        sx={{
                                                            backgroundColor: el.incoming
                                                                ? alpha(theme.palette.background.default, 1)
                                                                : theme.palette.primary.main,
                                                            borderRadius: 1,
                                                            display: "flex",
                                                            width: "max-content",
                                                        }}
                                                    >
                                                        <Stack spacing={1}>
                                                            {/* Display the link */}
                                                            <a
                                                                href={extractURL(el.message)}
                                                                target="_blank"
                                                                rel="noopener noreferrer"
                                                                style={{
                                                                    fontSize: "0.875rem", // Small font size
                                                                    color: el.incoming ? theme.palette.text.primary : "#fff",
                                                                    textDecoration: "none",
                                                                    wordBreak: "break-word", // Handle long URLs
                                                                }}
                                                            >
                                                                {truncateString(extractURL(el.message), 30)}
                                                            </a>

                                                            {/* Time received */}
                                                            <Typography
                                                                variant="caption"
                                                                color={el.incoming ? theme.palette.text.secondary : "#ddd"}
                                                                sx={{
                                                                    fontSize: "0.7rem", // Small font size
                                                                    textAlign: "right",
                                                                }}
                                                            >
                                                                {convertToIST(el.time)}
                                                            </Typography>
                                                        </Stack>
                                                    </Box>
                                                </Stack>
                                            );
                                        }
                                    })
                                case 2:
                                    return current_messages.map((el) => {
                                        if (el.type === "msg" && el.subtype === "DOCUMENT") {
                                            return (
                                                <DocMsg el={el} />
                                            )
                                        }
                                    })
                            }
                        })()
                    }

                </Stack>
            </Stack>
        </Box>
    )
};

export default SharedMessages;